{"source":"#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    char numero[21];
    int n = 0;

    scanf("%[^\n]", numero);

    n = strlen(numero);

    if (n < 3 || (n == 3 && strcmp(numero, "127") <= 0))
    {
        printf("byte");
        return 0;
    }
    if (n < 5 || (n == 5 && strcmp(numero, "32767") <= 0))
    {
        printf("short");
        return 0;
    }
    if (n < 10 || (n == 10 && strcmp(numero, "2147483647") <= 0))
    {
        printf("int");
        return 0;
    }
    if (n < 19 || (n == 19 && strcmp(numero, "9223372036854775807") <= 0))
    {
        printf("long");
        return 0;
    }
    else
    {
        printf("BigInteger");
        return 0;
    }
    return 0;
}"}
